    reg clk;
    reg reset;
    wire [3:0] q;

    // 2. Instantiate TopModule dut ( ... );
    TopModule dut (
        .clk(clk),
        .reset(reset),
        .q(q)
    );

    // 3. Stimulus & self-checking:
    integer errors = 0;

    // Clock generation
    always #5 clk = ~clk; // 10ns period

    initial begin
        // Initialize signals
        clk = 0;
        reset = 0;

        // Apply reset
