        repeat (20) begin
            #10; // Wait for clock edge
            if (q !== (q + 1) % 10) begin
                errors = errors + 1;
                $display("Error at time %0t: q = %b, expected = %b", $time, q, (q + 1) % 10);
            end
        end

        // Final check for reset functionality
        reset = 1; #10; // Assert reset
        if (q !== 4'b0000) begin
            errors = errors + 1;
            $display("Error at time %0t: q = %b, expected = 0000", $time, q);
        end
        reset = 0; #10; // Release reset

        // Check final state after reset
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end
endmodule
